def current_rows(events):
    best = {}
    for e in events:
        id_, et, seq, op, val = e['id'], e['event_time'], e['seq'], e['op'], e['value']
        current = (et, seq)
        if id_ not in best or current > best[id_][0]:
            best[id_] = (current, op, val)

    result = []
    for id_, (_, op, val) in best.items():
        if op != 'D':
            result.append({'id': id_, 'value': val})

    result.sort(key=lambda x: x['id'])
    return result
