import heapq

def stable_toposort(graph):
    # Validate dependencies and compute indegrees
    indegree = {node: 0 for node in graph}
    dependents = {node: [] for node in graph}  # reverse adjacency list

    for node, deps in graph.items():
        for dep in deps:
            if dep not in graph:
                raise ValueError(f"Missing dependency: {dep}")
            indegree[node] += 1
            dependents[dep].append(node)

    # Stable selection using insertion order index
    index = {node: i for i, node in enumerate(graph)}
    heap = []
    for node in graph:
        if indegree[node] == 0:
            heapq.heappush(heap, (index[node], node))

    result = []
    while heap:
        _, node = heapq.heappop(heap)
        result.append(node)
        for dep in dependents[node]:
            indegree[dep] -= 1
            if indegree[dep] == 0:
                heapq.heappush(heap, (index[dep], dep))

    if len(result) != len(graph):
        raise ValueError("Cycle detected in graph")

    return result
