def schema_drift(expected, actual):
    def collect_leaf_paths(d, prefix=""):
        """Return all dotted leaf paths for a nested dict, given a prefix."""
        paths = []
        if not isinstance(d, dict):
            # Should only be called on dicts, but handle leaf for safety.
            if prefix:
                paths.append(prefix)
            return paths
        for key in sorted(d.keys()):
            new_prefix = f"{prefix}.{key}" if prefix else key
            paths.extend(collect_leaf_paths(d[key], new_prefix))
        return paths

    def diff(exp, act, path=""):
        diffs = []
        all_keys = set(exp.keys()) | set(act.keys())
        for key in sorted(all_keys):
            new_path = f"{path}.{key}" if path else key
            if key not in act:
                # Missing field
                if isinstance(exp[key], dict):
                    diffs.extend(collect_leaf_paths(exp[key], new_path))
                else:
                    diffs.append(new_path)
            elif key not in exp:
                # Extra field
                if isinstance(act[key], dict):
                    diffs.extend(collect_leaf_paths(act[key], new_path))
                else:
                    diffs.append(new_path)
            else:
                exp_val = exp[key]
                act_val = act[key]
                if isinstance(exp_val, dict) and isinstance(act_val, dict):
                    diffs.extend(diff(exp_val, act_val, new_path))
                elif isinstance(exp_val, dict) or isinstance(act_val, dict):
                    # One is dict, the other is leaf -> type mismatch
                    diffs.append(new_path)
                else:
                    # Both are leaves (strings) – compare type strings
                    if exp_val != act_val:
                        diffs.append(new_path)
        return diffs

    result = diff(expected, actual)
    return sorted(result)
